/**
 * usbIds.js — vendor / product / class names from the linux-usb.org usb.ids
 * list (BSD-3-Clause option of its dual licence; see docs/ACKNOWLEDGMENTS.md).
 *
 * The data (src/data/usb-ids.json, ~750 KB, generated by
 * scripts/build-usb-ids.mjs) is loaded lazily with a dynamic import, so it is a
 * separate chunk that is only fetched the first time something asks for it.
 *
 * All lookups are async (they await the one-time load) and resolve to null when
 * nothing matches. `parseVidPid` and `formatVidPid` are pure and synchronous.
 */

let dbPromise = null;
let indexed = null;

/** Load (once) and index the data set. Pass `data` to inject a fixture in tests. */
export function loadUsbIds(data) {
  if (data) {
    dbPromise = Promise.resolve(data);
    indexed = null;
  }
  if (!dbPromise) {
    dbPromise = import('../data/usb-ids.json').then((m) => m.default || m);
  }
  return dbPromise.then(index);
}

/** Forget the cached data (tests). */
export function resetUsbIds() {
  dbPromise = null;
  indexed = null;
}

function index(data) {
  if (indexed && indexed.data === data) return indexed;
  const vendors = new Map();
  for (const [vid, name, products] of data.vendors) {
    vendors.set(vid, { vid, name, products: new Map(products) });
  }
  const classes = new Map();
  for (const [c, name, subs] of data.classes) {
    classes.set(c, { name, subs: new Map(subs.map(([s, sn, ps]) => [s, { name: sn, protos: new Map(ps) }])) });
  }
  indexed = { data, vendors, classes };
  return indexed;
}

/** Version/date of the loaded data, e.g. { version: '2026.06.26', date: '...' }. */
export async function usbIdsVersion() {
  const { data } = await loadUsbIds();
  return { version: data.version, date: data.date, license: data.license, header: data.header };
}

const hex4 = (n) => n.toString(16).padStart(4, '0');

/**
 * Parse "1d6b:0002", "0x10C4", "10c4:ea60", "ID 10c4:ea60", "10C4 EA60", "10c4,ea60".
 * Returns { vid, pid } (pid null when absent) or null if the text isn't an id.
 * A bare single hex token is only taken as a VID when it is 0x-prefixed or
 * exactly 4 hex digits, so "ch340" / "ftdi" stay name searches.
 */
export function parseVidPid(text) {
  if (typeof text !== 'string') return null;
  const s = text.trim().replace(/^id\s+/i, '');
  if (!s) return null;
  const tok = (t) => {
    const m = /^(?:0x)?([0-9a-f]{1,4})$/i.exec(t);
    return m ? parseInt(m[1], 16) : null;
  };
  const parts = s.split(/[\s:,/\-]+/).filter(Boolean);
  if (parts.length === 1) {
    if (!/^0x[0-9a-f]{1,4}$/i.test(parts[0]) && !/^[0-9a-f]{4}$/i.test(parts[0])) return null;
    const vid = tok(parts[0]);
    return vid == null ? null : { vid, pid: null };
  }
  if (parts.length === 2) {
    const vid = tok(parts[0]);
    const pid = tok(parts[1]);
    if (vid == null || pid == null) return null;
    return { vid, pid };
  }
  return null;
}

export function formatVidPid(vid, pid) {
  return pid == null ? hex4(vid) : `${hex4(vid)}:${hex4(pid)}`;
}

/** { vid, name } or null. */
export async function lookupVendor(vid) {
  const { vendors } = await loadUsbIds();
  const v = vendors.get(vid);
  return v ? { vid, name: v.name } : null;
}

/** { vid, pid, vendor, product } (product null when the vendor is known but the PID is not) or null. */
export async function lookupProduct(vid, pid) {
  const { vendors } = await loadUsbIds();
  const v = vendors.get(vid);
  if (!v) return null;
  return { vid, pid, vendor: v.name, product: v.products.get(pid) ?? null };
}

/** { class, subclass, protocol } names, each null when unknown. subclass/protocol optional. */
export async function lookupClass(c, s, p) {
  const { classes } = await loadUsbIds();
  const cls = classes.get(c);
  if (!cls) return null;
  const sub = s != null ? cls.subs.get(s) : null;
  return {
    class: cls.name,
    subclass: sub ? sub.name : null,
    protocol: sub && p != null ? sub.protos.get(p) ?? null : null
  };
}

/**
 * Free-text search over vendor and product names (and an id if the text parses
 * as one). Ranked: exact id > name equals > name starts-with > word starts-with
 * > substring; shorter names first within a rank. Returns
 * [{ kind: 'vendor'|'product', vid, pid?, vendor, name, score }].
 */
export async function searchIds(query, limit = 50) {
  const { vendors } = await loadUsbIds();
  const q = String(query || '').trim().toLowerCase();
  if (!q) return [];
  const out = [];
  const id = parseVidPid(q);
  if (id) {
    const v = vendors.get(id.vid);
    if (v) {
      if (id.pid == null) {
        out.push({ kind: 'vendor', vid: v.vid, vendor: v.name, name: v.name, score: 1000 });
        for (const [pid, name] of v.products) out.push({ kind: 'product', vid: v.vid, pid, vendor: v.name, name, score: 900 });
      } else {
        const name = v.products.get(id.pid);
        if (name != null) out.push({ kind: 'product', vid: v.vid, pid: id.pid, vendor: v.name, name, score: 1000 });
        else out.push({ kind: 'vendor', vid: v.vid, vendor: v.name, name: v.name, score: 800 });
      }
    }
    if (out.length) return out.slice(0, limit);
  }
  const rank = (name) => {
    const n = name.toLowerCase();
    if (n === q) return 500;
    if (n.startsWith(q)) return 400;
    if (n.split(/[^a-z0-9]+/).some((w) => w.startsWith(q))) return 300;
    if (n.includes(q)) return 200;
    return 0;
  };
  for (const v of vendors.values()) {
    const vr = rank(v.name);
    if (vr) out.push({ kind: 'vendor', vid: v.vid, vendor: v.name, name: v.name, score: vr - v.name.length / 100 });
    for (const [pid, name] of v.products) {
      const pr = rank(name);
      if (pr) out.push({ kind: 'product', vid: v.vid, pid, vendor: v.name, name, score: pr - name.length / 100 });
    }
  }
  out.sort((a, b) => b.score - a.score || a.vid - b.vid || (a.pid ?? -1) - (b.pid ?? -1));
  return out.slice(0, limit);
}
